#include "stdafx.h"#include "ControlBuilderE.h"#include "../ControlBuilderH/CBPool.h"__declspec(dllimport) KCBPool g_Pool;using namespace nRSUx;SParamInfo RsuConnectParamInfo( LPCSTR pszPointName, LPSTR pszIOtype, LPCSTR pSuffix ){  SParamInfo info;  char splitName[128];  strcpy_s( splitName, pszPointName );  char *p = splitName;  while( *p )  {    *p = toupper( *p );    ++p;  }  LPSTR pField = strrchr( splitName, '.' );  if( !pField )    return info;  *pField = 0;  ++pField;  LPBYTE pVarAddr = NULL;  eVarType type = evtHZ;  bool b = g_Pool.GetVar( pSuffix, splitName, pField, &pVarAddr, &type );  if( !b )    return info;  switch( type )  {  case evtDouble:    info << (double*)pVarAddr;    break;  case evtBool:    info << (bool*)pVarAddr;    break;  }  return info;}